// County-depth card notes: hathi-batch2-enrich.json
{ const E={"pbu15-church-sec-33-t39n-r16w": {"st": " Peet's History of Burnett County (1902, pp. 45-46): the April post office was new in 1902, in sec. 33 of this township (T39N R16W) near the south line. That makes this church corner a likely center for the April neighborhood, but the post office building is not placed.", "src": [["History of Burnett County (Rev. Emerson W. Peet, 1902), pp. 45-46, via HathiTrust", "https://catalog.hathitrust.org/"]]}}; for(const p of DATA.points){ const x=E[p.id]; if(!x) continue; if(x.fix) p.st=(p.st||"").replace(x.fix[0],x.fix[1]); p.st=(p.st||"")+x.st; (p.src=p.src||[]).push(...x.src); } }
